{
  "kind": "emission",
  "schema": {
    "$defs": {
      "ConstantIndex": {
        "additionalProperties": false,
        "description": "Wavelength-independent complex refractive index n + ik.",
        "properties": {
          "kind": {
            "const": "constant_index",
            "default": "constant_index",
            "title": "Kind",
            "type": "string"
          },
          "n_real": {
            "description": "Real part of the refractive index.",
            "title": "N Real",
            "type": "number"
          },
          "n_imag": {
            "default": 0.0,
            "description": "Extinction coefficient k (>= 0 for loss).",
            "minimum": 0,
            "title": "N Imag",
            "type": "number"
          }
        },
        "required": [
          "n_real"
        ],
        "title": "ConstantIndex",
        "type": "object"
      },
      "ConstantPermittivity": {
        "additionalProperties": false,
        "description": "Wavelength-independent complex relative permittivity.",
        "properties": {
          "kind": {
            "const": "constant_permittivity",
            "default": "constant_permittivity",
            "title": "Kind",
            "type": "string"
          },
          "eps_real": {
            "title": "Eps Real",
            "type": "number"
          },
          "eps_imag": {
            "default": 0.0,
            "minimum": 0,
            "title": "Eps Imag",
            "type": "number"
          }
        },
        "required": [
          "eps_real"
        ],
        "title": "ConstantPermittivity",
        "type": "object"
      },
      "Cylinder": {
        "additionalProperties": false,
        "description": "Flat-ended cylinder with axis along z.",
        "properties": {
          "kind": {
            "const": "cylinder",
            "default": "cylinder",
            "title": "Kind",
            "type": "string"
          },
          "radius_nm": {
            "exclusiveMinimum": 0,
            "title": "Radius Nm",
            "type": "number"
          },
          "length_nm": {
            "exclusiveMinimum": 0,
            "title": "Length Nm",
            "type": "number"
          }
        },
        "required": [
          "radius_nm",
          "length_nm"
        ],
        "title": "Cylinder",
        "type": "object"
      },
      "Dipole": {
        "additionalProperties": false,
        "description": "A point electric dipole emitter.",
        "properties": {
          "position_nm": {
            "default": [
              0.0,
              0.0,
              0.0
            ],
            "maxItems": 3,
            "minItems": 3,
            "prefixItems": [
              {
                "type": "number"
              },
              {
                "type": "number"
              },
              {
                "type": "number"
              }
            ],
            "title": "Position Nm",
            "type": "array"
          },
          "orientation": {
            "default": [
              0.0,
              0.0,
              1.0
            ],
            "description": "Dipole moment direction.",
            "maxItems": 3,
            "minItems": 3,
            "prefixItems": [
              {
                "type": "number"
              },
              {
                "type": "number"
              },
              {
                "type": "number"
              }
            ],
            "title": "Orientation",
            "type": "array"
          }
        },
        "title": "Dipole",
        "type": "object"
      },
      "Drude": {
        "additionalProperties": false,
        "description": "eps(w) = eps_inf - wp^2 / (w^2 + i*gamma*w), energies in eV.",
        "properties": {
          "kind": {
            "const": "drude",
            "default": "drude",
            "title": "Kind",
            "type": "string"
          },
          "eps_inf": {
            "default": 1.0,
            "title": "Eps Inf",
            "type": "number"
          },
          "wp_ev": {
            "description": "Plasma frequency in eV.",
            "exclusiveMinimum": 0,
            "title": "Wp Ev",
            "type": "number"
          },
          "gamma_ev": {
            "description": "Damping rate in eV.",
            "minimum": 0,
            "title": "Gamma Ev",
            "type": "number"
          }
        },
        "required": [
          "wp_ev",
          "gamma_ev"
        ],
        "title": "Drude",
        "type": "object"
      },
      "DrudeLorentz": {
        "additionalProperties": false,
        "description": "eps(w) = eps_inf - wp^2/(w^2 + i g w) + sum_j d_j w0_j^2 / (w0_j^2 - w^2 - i G_j w).\n\nThe form FDTD needs for auxiliary-differential-equation dispersion.\nFit one to measured data with :func:`lightsmith.materials_fit.fit_drude_lorentz`.",
        "properties": {
          "kind": {
            "const": "drude_lorentz",
            "default": "drude_lorentz",
            "title": "Kind",
            "type": "string"
          },
          "eps_inf": {
            "default": 1.0,
            "title": "Eps Inf",
            "type": "number"
          },
          "wp_ev": {
            "default": 0.0,
            "minimum": 0,
            "title": "Wp Ev",
            "type": "number"
          },
          "gamma_ev": {
            "default": 0.0,
            "minimum": 0,
            "title": "Gamma Ev",
            "type": "number"
          },
          "poles": {
            "items": {
              "$ref": "#/$defs/LorentzPole"
            },
            "title": "Poles",
            "type": "array"
          }
        },
        "title": "DrudeLorentz",
        "type": "object"
      },
      "LayeredSphere": {
        "additionalProperties": false,
        "description": "Core-shell / multilayer sphere. The particle's `material` is the core;\n`shells` are listed from the inside out.",
        "properties": {
          "kind": {
            "const": "layered_sphere",
            "default": "layered_sphere",
            "title": "Kind",
            "type": "string"
          },
          "core_radius_nm": {
            "exclusiveMinimum": 0,
            "title": "Core Radius Nm",
            "type": "number"
          },
          "shells": {
            "items": {
              "$ref": "#/$defs/Shell"
            },
            "minItems": 1,
            "title": "Shells",
            "type": "array"
          }
        },
        "required": [
          "core_radius_nm",
          "shells"
        ],
        "title": "LayeredSphere",
        "type": "object"
      },
      "LibraryMaterial": {
        "additionalProperties": false,
        "description": "Measured n, k bundled with lightsmith, e.g. ``{\"kind\": \"library\", \"name\": \"Au\",\n\"dataset\": \"Johnson-Christy\"}``. Linear interpolation in n and k, no extrapolation.\n\nNames and datasets accept aliases (\"gold\", \"JC\") and are stored in canonical form;\nan omitted dataset is filled with the material's default so the spec stays\nreproducible. See :func:`list_materials`.",
        "properties": {
          "kind": {
            "const": "library",
            "default": "library",
            "title": "Kind",
            "type": "string"
          },
          "name": {
            "description": "Material, e.g. 'Au', 'Ag', 'Al', 'Cu', 'Si', 'TiO2', 'SiO2', 'H2O'.",
            "title": "Name",
            "type": "string"
          },
          "dataset": {
            "anyOf": [
              {
                "type": "string"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "description": "Dataset, e.g. 'Johnson-Christy'; omitted = material default.",
            "title": "Dataset"
          }
        },
        "required": [
          "name"
        ],
        "title": "LibraryMaterial",
        "type": "object"
      },
      "LorentzPole": {
        "additionalProperties": false,
        "properties": {
          "delta_eps": {
            "description": "Oscillator strength (permittivity step).",
            "title": "Delta Eps",
            "type": "number"
          },
          "omega0_ev": {
            "description": "Resonance energy in eV.",
            "exclusiveMinimum": 0,
            "title": "Omega0 Ev",
            "type": "number"
          },
          "gamma_ev": {
            "description": "Damping in eV.",
            "minimum": 0,
            "title": "Gamma Ev",
            "type": "number"
          }
        },
        "required": [
          "delta_eps",
          "omega0_ev",
          "gamma_ev"
        ],
        "title": "LorentzPole",
        "type": "object"
      },
      "Particle": {
        "additionalProperties": false,
        "properties": {
          "shape": {
            "discriminator": {
              "mapping": {
                "cylinder": "#/$defs/Cylinder",
                "layered_sphere": "#/$defs/LayeredSphere",
                "sphere": "#/$defs/Sphere",
                "spheroid": "#/$defs/Spheroid"
              },
              "propertyName": "kind"
            },
            "oneOf": [
              {
                "$ref": "#/$defs/Sphere"
              },
              {
                "$ref": "#/$defs/Spheroid"
              },
              {
                "$ref": "#/$defs/Cylinder"
              },
              {
                "$ref": "#/$defs/LayeredSphere"
              }
            ],
            "title": "Shape"
          },
          "material": {
            "description": "Particle material (the core for layered spheres).",
            "discriminator": {
              "mapping": {
                "constant_index": "#/$defs/ConstantIndex",
                "constant_permittivity": "#/$defs/ConstantPermittivity",
                "drude": "#/$defs/Drude",
                "drude_lorentz": "#/$defs/DrudeLorentz",
                "library": "#/$defs/LibraryMaterial",
                "tabulated": "#/$defs/Tabulated"
              },
              "propertyName": "kind"
            },
            "oneOf": [
              {
                "$ref": "#/$defs/ConstantIndex"
              },
              {
                "$ref": "#/$defs/ConstantPermittivity"
              },
              {
                "$ref": "#/$defs/Drude"
              },
              {
                "$ref": "#/$defs/DrudeLorentz"
              },
              {
                "$ref": "#/$defs/Tabulated"
              },
              {
                "$ref": "#/$defs/LibraryMaterial"
              }
            ],
            "title": "Material"
          },
          "position_nm": {
            "default": [
              0.0,
              0.0,
              0.0
            ],
            "maxItems": 3,
            "minItems": 3,
            "prefixItems": [
              {
                "type": "number"
              },
              {
                "type": "number"
              },
              {
                "type": "number"
              }
            ],
            "title": "Position Nm",
            "type": "array"
          }
        },
        "required": [
          "shape",
          "material"
        ],
        "title": "Particle",
        "type": "object"
      },
      "RadiationPatternRequest": {
        "additionalProperties": false,
        "description": "Radiated power per solid angle. theta is measured from +z, phi from +x.",
        "properties": {
          "theta_deg": {
            "items": {
              "type": "number"
            },
            "minItems": 1,
            "title": "Theta Deg",
            "type": "array"
          },
          "phi_deg": {
            "default": [
              0.0,
              90.0
            ],
            "items": {
              "type": "number"
            },
            "minItems": 1,
            "title": "Phi Deg",
            "type": "array"
          },
          "wavelengths_nm": {
            "items": {
              "type": "number"
            },
            "minItems": 1,
            "title": "Wavelengths Nm",
            "type": "array"
          }
        },
        "required": [
          "theta_deg",
          "wavelengths_nm"
        ],
        "title": "RadiationPatternRequest",
        "type": "object"
      },
      "Shell": {
        "additionalProperties": false,
        "properties": {
          "thickness_nm": {
            "exclusiveMinimum": 0,
            "title": "Thickness Nm",
            "type": "number"
          },
          "material": {
            "discriminator": {
              "mapping": {
                "constant_index": "#/$defs/ConstantIndex",
                "constant_permittivity": "#/$defs/ConstantPermittivity",
                "drude": "#/$defs/Drude",
                "drude_lorentz": "#/$defs/DrudeLorentz",
                "library": "#/$defs/LibraryMaterial",
                "tabulated": "#/$defs/Tabulated"
              },
              "propertyName": "kind"
            },
            "oneOf": [
              {
                "$ref": "#/$defs/ConstantIndex"
              },
              {
                "$ref": "#/$defs/ConstantPermittivity"
              },
              {
                "$ref": "#/$defs/Drude"
              },
              {
                "$ref": "#/$defs/DrudeLorentz"
              },
              {
                "$ref": "#/$defs/Tabulated"
              },
              {
                "$ref": "#/$defs/LibraryMaterial"
              }
            ],
            "title": "Material"
          }
        },
        "required": [
          "thickness_nm",
          "material"
        ],
        "title": "Shell",
        "type": "object"
      },
      "Sphere": {
        "additionalProperties": false,
        "properties": {
          "kind": {
            "const": "sphere",
            "default": "sphere",
            "title": "Kind",
            "type": "string"
          },
          "radius_nm": {
            "exclusiveMinimum": 0,
            "title": "Radius Nm",
            "type": "number"
          }
        },
        "required": [
          "radius_nm"
        ],
        "title": "Sphere",
        "type": "object"
      },
      "Spheroid": {
        "additionalProperties": false,
        "description": "Spheroid with symmetry axis along z.",
        "properties": {
          "kind": {
            "const": "spheroid",
            "default": "spheroid",
            "title": "Kind",
            "type": "string"
          },
          "semi_axis_xy_nm": {
            "exclusiveMinimum": 0,
            "title": "Semi Axis Xy Nm",
            "type": "number"
          },
          "semi_axis_z_nm": {
            "exclusiveMinimum": 0,
            "title": "Semi Axis Z Nm",
            "type": "number"
          }
        },
        "required": [
          "semi_axis_xy_nm",
          "semi_axis_z_nm"
        ],
        "title": "Spheroid",
        "type": "object"
      },
      "Tabulated": {
        "additionalProperties": false,
        "description": "Tabulated n, k data, linearly interpolated (no extrapolation).",
        "properties": {
          "kind": {
            "const": "tabulated",
            "default": "tabulated",
            "title": "Kind",
            "type": "string"
          },
          "wavelength_nm": {
            "items": {
              "type": "number"
            },
            "title": "Wavelength Nm",
            "type": "array"
          },
          "n_real": {
            "items": {
              "type": "number"
            },
            "title": "N Real",
            "type": "array"
          },
          "n_imag": {
            "items": {
              "type": "number"
            },
            "title": "N Imag",
            "type": "array"
          },
          "source": {
            "anyOf": [
              {
                "type": "string"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "description": "Citation / provenance of the data.",
            "title": "Source"
          }
        },
        "required": [
          "wavelength_nm",
          "n_real",
          "n_imag"
        ],
        "title": "Tabulated",
        "type": "object"
      },
      "WavelengthRange": {
        "additionalProperties": false,
        "properties": {
          "start_nm": {
            "exclusiveMinimum": 0,
            "title": "Start Nm",
            "type": "number"
          },
          "stop_nm": {
            "exclusiveMinimum": 0,
            "title": "Stop Nm",
            "type": "number"
          },
          "num": {
            "minimum": 1,
            "title": "Num",
            "type": "integer"
          }
        },
        "required": [
          "start_nm",
          "stop_nm",
          "num"
        ],
        "title": "WavelengthRange",
        "type": "object"
      }
    },
    "additionalProperties": false,
    "description": "A point dipole near particles in a homogeneous medium.\n\nGives the decay-rate (Purcell) enhancement, the radiative enhancement, the efficiency and the radiation\npattern, all relative to the same dipole in the medium alone.",
    "properties": {
      "kind": {
        "const": "emission",
        "default": "emission",
        "title": "Kind",
        "type": "string"
      },
      "particles": {
        "items": {
          "$ref": "#/$defs/Particle"
        },
        "title": "Particles",
        "type": "array"
      },
      "medium_index": {
        "default": 1.0,
        "description": "Real refractive index of the host medium.",
        "exclusiveMinimum": 0,
        "title": "Medium Index",
        "type": "number"
      },
      "dipole": {
        "$ref": "#/$defs/Dipole",
        "default": {
          "position_nm": [
            0.0,
            0.0,
            0.0
          ],
          "orientation": [
            0.0,
            0.0,
            1.0
          ]
        }
      },
      "wavelengths": {
        "anyOf": [
          {
            "items": {
              "type": "number"
            },
            "type": "array"
          },
          {
            "$ref": "#/$defs/WavelengthRange"
          }
        ],
        "description": "Vacuum wavelengths in nm.",
        "title": "Wavelengths"
      },
      "radiation_pattern": {
        "anyOf": [
          {
            "$ref": "#/$defs/RadiationPatternRequest"
          },
          {
            "type": "null"
          }
        ],
        "default": null
      },
      "options": {
        "additionalProperties": {
          "additionalProperties": true,
          "type": "object"
        },
        "title": "Options",
        "type": "object"
      }
    },
    "required": [
      "wavelengths"
    ],
    "title": "EmissionProblem",
    "type": "object"
  },
  "conventions": "Lightsmith conventions (fixed; changing them needs a schema version bump):\n- Lengths in nm. Wavelengths are vacuum wavelengths in nm.\n- Time dependence exp(-i omega t): absorbing materials have Im(eps) > 0 and Im(n) > 0.\n- Cross sections in nm^2; efficiencies Q = C / (pi r_eq^2), r_eq = volume-equivalent radius of all particles.\n- layer_stack / periodic: layers listed from the superstrate (incidence side) to the substrate; light travels +z.\n  R is measured in the superstrate, T in the substrate.\n- mode: cross-section in the xy plane, propagation along +z.\n- device: ports are planes whose normal is the axis where size_nm is zero; direction is into the device.\n- problem.options[<method or backend name>] holds solver options, validated by that backend.\n- Materials: {\"kind\": \"constant_index\", \"n_real\": .., \"n_imag\": ..}, {\"kind\": \"library\", \"name\": \"Au\"},\n  drude, drude_lorentz, tabulated, constant_permittivity. FDTD needs dispersive models (fit_drude_lorentz).\n- Results carry provenance and warnings: read the warnings before trusting the numbers.\n",
  "backends": [
    {
      "name": "lightsmith-mie",
      "method": "mie",
      "available": true,
      "gpu": true,
      "auto_rank": 0
    },
    {
      "name": "lightsmith-fdtd",
      "method": "fdtd",
      "available": true,
      "gpu": true,
      "auto_rank": 1
    }
  ],
  "example": {
    "kind": "emission",
    "particles": [
      {
        "shape": {
          "kind": "sphere",
          "radius_nm": 40
        },
        "material": {
          "kind": "library",
          "name": "Au",
          "dataset": "Johnson-Christy"
        }
      }
    ],
    "medium_index": 1.33,
    "dipole": {
      "position_nm": [
        0,
        0,
        50
      ],
      "orientation": [
        0,
        0,
        1
      ]
    },
    "wavelengths": {
      "start_nm": 500,
      "stop_nm": 700,
      "num": 41
    }
  }
}

